tasks = ["BornholmBitextMining","NorwegianCourtsBitextMining","AngryTweetsClassification","DanishPoliticalCommentsClassification","DalajClassification","DKHateClassification","LccSentimentClassification","MassiveIntentClassification","MassiveScenarioClassification","NordicLangClassification","NoRecClassification","NorwegianParliamentClassification","ScalaClassification","SwedishSentimentClassification","SweRecClassification","DanFEVER","NorQuadRetrieval","SNLRetrieval","SwednRetrieval","SweFaqRetrieval","TV2Nordretrieval","TwitterHjerneRetrieval","SNLHierarchicalClusteringS2S","SNLHierarchicalClusteringP2P","SwednClusteringP2P","SwednClusteringS2S","VGHierarchicalClusteringS2S","VGHierarchicalClusteringP2P"]
def score(fn):
    d = json.load(open(fn))
    s = d.get('scores') or {}
    for k in s:
        v = s[k][0].get('main_score')
        if v is not None: return v
    return None
res = []
for md in sorted(os.listdir(base)):
    mdir = os.path.join(base, md)
    if not os.path.isdir(mdir): continue
    have = {}
